const {chromium}=require('playwright'),http=require('http'),fs=require('fs'),path=require('path'),assert=require('assert/strict'),os=require('os');
const repo=path.resolve(__dirname,'../..'),out=process.env.SAMBAADM_DEMOTE_SCREENSHOTS||fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-demote-'));
const server=http.createServer((req,res)=>{if(req.url==='/domain-demote.js'){res.setHeader('Content-Type','application/javascript');res.end(fs.readFileSync(path.join(repo,'internal/web/static/js/domain-demote.js')));}else if(req.url==='/wizard.css'){res.setHeader('Content-Type','text/css');res.end(fs.readFileSync(path.join(repo,'internal/domaininit/assets/wizard.css')));}else res.end('<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="csrf-token" content="csrf-test"><link rel="stylesheet" href="/wizard.css"><script defer src="/domain-demote.js"></script></head><body><main class="di-shell"><div data-domain-demote></div></main></body></html>');});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch();try{const page=await browser.newPage({viewport:{width:1280,height:1000}}),errors=[],writes=[];page.on('pageerror',e=>errors.push(e.message));let state='running',reject=true;
await page.route('**/api/v1/domain-demote**',async route=>{const req=route.request(),url=new URL(req.url());let json,status=200;if(req.method()==='POST'){assert.equal(req.headers()['x-csrf-token'],'csrf-test');const input=req.postDataJSON();writes.push({path:url.pathname,...input});assert.equal(input.password,'PrivateA1!');if(url.pathname.endsWith('/plan')){if(reject){status=409;json={error:'Сначала передайте роли FSMO'};}else json={revision:'a'.repeat(64),checks:['FSMO переданы','SYSVOL и права совпадают','Репозитории и пакеты доступны'],steps:['Скачать пакеты и создать защитную копию','Снять роль DC','Настроить сервер как член домена','Проверить доверие, Winbind и helper'],packages:['samba = 4.19','samba-winbind = 4.19']};}else{assert.equal(input.confirm,'dc2.corp.example');json={id:'b'.repeat(32),node:input.node,source:input.source,state:'queued'};}}else if(url.searchParams.has('id'))json={id:'b'.repeat(32),node:'dc2.corp.example',source:'dc1.corp.example',state,log:['Репозитории проверены','Роль DC снята'],error:state==='needs_member'?'Пакет недоступен. Настройте репозиторий.':''};else json={realm:'corp.example',controllers:[{dns:'dc1.corp.example',site:'Main',rodc:false},{dns:'dc2.corp.example',site:'Branch',rodc:true}],nodes:['dc1.corp.example','dc2.corp.example']};await route.fulfill({status,json});});
await page.goto('http://127.0.0.1:'+server.address().port+'/?node=dc2.corp.example');await page.getByLabel('Администратор домена').fill('Administrator@corp.example');await page.getByLabel('Пароль',{exact:true}).fill('PrivateA1!');await page.locator('.di-shell').screenshot({path:path.join(out,'demote-parameters.png')});await page.getByRole('button',{name:'Проверить и показать план'}).click();await page.getByRole('status').filter({hasText:'Сначала передайте'}).waitFor();assert.equal(writes.length,1);reject=false;await page.getByRole('button',{name:'Проверить и показать план'}).click();await page.getByRole('heading',{name:'План перехода в член домена'}).waitFor();await page.locator('.di-shell').screenshot({path:path.join(out,'demote-preview.png')});await page.getByLabel('Для подтверждения введите dc2.corp.example').fill('dc2.corp.example');await page.getByRole('button',{name:'Снять роль и настроить членство'}).click();await page.getByRole('heading',{name:'Задание принято'}).waitFor();assert(!JSON.stringify(await page.evaluate(()=>({...sessionStorage}))).includes('PrivateA1!'));await page.reload();await page.getByRole('heading',{name:'Выполняется переход в член домена'}).waitFor();assert.equal(writes.filter(x=>x.path.endsWith('/start')).length,1);state='needs_member';await page.getByRole('heading',{name:'Нужно завершить настройку члена домена'}).waitFor();await page.getByLabel('Администратор домена').fill('Administrator@corp.example');await page.getByLabel('Пароль',{exact:true}).fill('PrivateA1!');await page.locator('.di-shell').screenshot({path:path.join(out,'demote-resume.png')});state='completed';await page.getByRole('button',{name:'Проверить и завершить членство'}).click();await page.getByRole('heading',{name:'Сервер — член домена'}).waitFor();assert.equal(writes.filter(x=>x.path.endsWith('/resume')).length,1);await page.setViewportSize({width:390,height:844});assert(!await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth));await page.locator('.di-shell').screenshot({path:path.join(out,'demote-mobile.png')});assert.deepEqual(errors,[]);console.log('PASS DC retirement preview, FSMO gate, explicit confirmation, credential isolation, no replay, member-only resume and mobile; screenshots:',out);
}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
